.account-card { margin-top:auto; display:flex; align-items:center; gap:9px; padding: 12px 8px; border-top:1px solid #ecebe8; color:#383d48; }.account-card .avatar { width:29px;height:29px;display:grid;place-items:center;border-radius:50%;background:#e7c3ad;color:#7b4534;font-size:10px;font-weight:700; }.account-card div:nth-child(2) { display:grid; gap:2px; flex:1; }.account-card strong { font-size:12px; }.account-card span { color:#888b92;font-size:10px; }.account-card svg { width:15px;height:15px;color:#898b92; }
.content { min-width:0; display:flex; flex-direction:column; padding: 37px 46px 0; }.content header { display:flex; align-items:flex-start; justify-content:space-between; padding-bottom:25px; border-bottom:1px solid #ebebee; }.eyebrow { margin:0 0 4px; color:#8a8c94; font-size:12px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; } h1 { margin:0; font: 600 31px/1 Georgia, serif; letter-spacing:-.8px; } .close { width:31px;height:31px;border:0;border-radius:8px;background:#f6f6f7;color:#777a82;font-size:25px;line-height:1;cursor:pointer; }.close:hover { background:#eeeeef; }
.group { padding: 24px 0 4px; }.group h2 { margin:0 0 12px; color:#676b75; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; }.setting-row { display:flex; align-items:center; justify-content:space-between; gap:24px; min-height:66px; padding: 10px 0; border-bottom:1px solid #f0f0f1; }.setting-row h3 { margin:0 0 4px; font-size:14px; letter-spacing:-.1px; }.setting-row p, .placeholder p { margin:0; color:#8a8d96; font-size:12px; line-height:1.45; }.select-button { min-width:151px; display:flex; justify-content:space-between; align-items:center; padding:8px 10px; border:1px solid #e1e1e5; border-radius:7px; background:#fff; color:#4e525b; font-size:12px; cursor:pointer; }.select-button span { color:#868992; font-size:17px; line-height:.7; }.toggle { position:relative; flex:0 0 auto; width:38px; height:22px; padding:0; border:0; border-radius:99px; background:#d6d7dc; cursor:pointer; transition:.2s; }.toggle span { position:absolute; top:3px; left:3px; width:16px; height:16px; border-radius:50%; background:white; box-shadow:0 1px 2px #9a9ba2; transition:.2s; }.toggle.is-on { background:#5d68dc; }.toggle.is-on span { transform:translateX(16px); }
.appearance-group { padding-top:25px; }.appearance-options { display:flex; width:max-content; padding:3px; border-radius:8px; background:#f3f3f5; }.appearance-options button { min-width:72px; padding:7px 12px; border:0; border-radius:6px; background:transparent; color:#777b84; font-size:12px; cursor:pointer; }.appearance-options button.selected { background:#fff; color:#363b46; font-weight:600; box-shadow:0 1px 3px rgba(20,20,30,.12); }.placeholder { min-height:230px; }.placeholder p { font-size:14px; } footer { display:flex; align-items:center; justify-content:space-between; margin-top:auto; padding:18px 0 22px; border-top:1px solid #ebebee; color:#94969d; font-size:11px; } footer button { padding:8px 18px; border:0; border-radius:7px; background:#5864d4; color:#fff; font-size:12px; font-weight:600; cursor:pointer; box-shadow:0 2px 4px rgba(67,78,185,.22); }
@media (max-width: 650px) { .app-shell { padding:0; place-items:stretch; }.settings-window { min-height:100vh; border-radius:0; grid-template-columns:1fr; }.sidebar { padding:15px; border-right:0; border-bottom:1px solid #ecebe8; }.brand { padding:0 6px 12px; } nav { display:flex; overflow:auto; }.nav-item { width:auto; flex:0 0 auto; }.account-card { display:none; }.content { padding:28px 24px 0; }.setting-row { gap:12px; }.select-button { min-width:130px; }.appearance-options { width:100%; }.appearance-options button { flex:1; } }
